import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import {createRemoteLibrary} from '../lib/remote-library.mjs';import {createBubbleStyleLibrary} from '../lib/bubble-style-library.mjs';import {comicStyles} from '../public/comic-styles.js';
const root=path.resolve('..'),live=path.join(root,'production-comic-data-current'),audit=path.join(root,'verification/tail-width-round-double-20261023'),dataDir=path.join(audit,'publisher');fs.mkdirSync(dataDir,{recursive:true});if(!fs.existsSync(path.join(dataDir,'bubble-styles.local.json')))fs.copyFileSync(path.join(live,'bubble-styles.local.json'),path.join(dataDir,'bubble-styles.local.json'));
const library=createRemoteLibrary({dataDir,configPath:path.join(live,'library-session.local.json'),store:{db:{libraryFonts:[]}}}),cacheBefore=JSON.parse(fs.readFileSync(path.join(dataDir,'bubble-styles.local.json'),'utf8')),previous=JSON.parse(await(await library.remote('/api/revisions/'+cacheBefore.manifest.revisionId+'/download')).text()),publisher=createBubbleStyleLibrary({dataDir,library}),result=await publisher.publish();
fs.writeFileSync(path.join(audit,'publish-result.json'),JSON.stringify(result,null,2));fs.copyFileSync(path.join(dataDir,'bubble-styles.local.json'),path.join(live,'bubble-styles.local.json'));console.log(JSON.stringify(result));
const manifest=await publisher.readManifest({refresh:true}),cache=JSON.parse(fs.readFileSync(path.join(dataDir,'bubble-styles.local.json'),'utf8')),checks=[];assert.equal(manifest.items.length,54);for(const old of previous.items)assert.ok(manifest.items.some(s=>s.id===old.id),'Missing previous style '+old.id);
for(const style of comicStyles.filter(s=>s.id.startsWith('ref23-'))){const entry=cache.items[style.id];for(const [kind,revisionId,expected] of [['PNG',entry.revisionId,entry.sha256],['SVG',entry.svgRevisionId,entry.svgSha256]]){assert.ok(revisionId,style.id+' missing '+kind);const bytes=Buffer.from(await(await library.remote('/api/revisions/'+revisionId+'/download')).arrayBuffer()),actual=createHash('sha256').update(bytes).digest('hex');assert.equal(actual,expected);checks.push({id:style.id,kind,revisionId,sha256:actual,bytes:bytes.length,hashMatch:true});}}
assert.equal(checks.length,34);assert.ok(manifest.items.find(s=>s.id==='ref23-round-double').parts[0].contour);assert.equal(manifest.items.filter(s=>s.rays).length,6);assert.equal(manifest.items.filter(s=>s.preset).length,10);fs.writeFileSync(path.join(audit,'upload-verification.json'),JSON.stringify({ok:true,totalStyles:54,newStyles:17,roundDouble:1,thoughtFrames:6,personFrames:5,locationFrames:5,allOldStylesRetained:true,verifiedFiles:checks.length,manifestRevisionId:result.manifest.revisionId,checks},null,2));console.log(JSON.stringify({ok:true,newStyles:17,verifiedFiles:34,allOldStylesRetained:true}));
